const updateStockLine = `-- name: UpdateStockLine :execrows
update expense_items
   set item_type = $1, ingredient_id = $2, product_id = $3,
       description = $4, quantity = $5, unit_id = $6,
       qty_received = $7, amount = $8, unit_cost = $9,
       pack_qty_in_base = $10, presentation_id = $11,
       is_gift = $12, not_coming_qty = $13
 where id = $14 and expense_id = $15 and voided_at is null
`

type UpdateStockLineParams struct {
	ItemType       *StockItemType   `json:"item_type"`
	IngredientID   *int64           `json:"ingredient_id"`
	ProductID      *int64           `json:"product_id"`
	Description    string           `json:"description"`
	Quantity       decimal.Decimal  `json:"quantity"`
	UnitID         *int16           `json:"unit_id"`
	QtyReceived    *decimal.Decimal `json:"qty_received"`
	Amount         decimal.Decimal  `json:"amount"`
	UnitCost       decimal.Decimal  `json:"unit_cost"`
	PackQtyInBase  *decimal.Decimal `json:"pack_qty_in_base"`
	PresentationID *int64           `json:"presentation_id"`
	IsGift         bool             `json:"is_gift"`
	NotComingQty   decimal.Decimal  `json:"not_coming_qty"`
	ID             int64            `json:"id"`
	ExpenseID      int64            `json:"expense_id"`
}

// Corregir un renglón: lo pedido, lo que llegó, el empaque y el importe. Lo aplicado no se toca aquí:
// se mueve con su movimiento.
func (q *Queries) UpdateStockLine(ctx context.Context, arg UpdateStockLineParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateStockLine,
		arg.ItemType,
		arg.IngredientID,
		arg.ProductID,
		arg.Description,
		arg.Quantity,
		arg.UnitID,
		arg.QtyReceived,
		arg.Amount,
		arg.UnitCost,
		arg.PackQtyInBase,
		arg.PresentationID,
		arg.IsGift,
		arg.NotComingQty,
		arg.ID,
		arg.ExpenseID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const voidStockLine = `-- name: VoidStockLine :execrows
update expense_items set voided_at = now() where id = $1 and expense_id = $2 and voided_at is null
`

type VoidStockLineParams struct {
	ID        int64 `json:"id"`
	ExpenseID int64 `json:"expense_id"`
}

// Quitar un renglón en una corrección: se marca, no se borra (sus movimientos lo referencian).
func (q *Queries) VoidStockLine(ctx context.Context, arg VoidStockLineParams) (int64, error) {
	result, err := q.db.Exec(ctx, voidStockLine, arg.ID, arg.ExpenseID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
